# Verify full rule across demos programmatically.
def solve(I):
    H,W=len(I),len(I[0])
    cnt=collections.Counter(x for r in I for x in r)
    bg=max(cnt,key=lambda c:cnt[c])
    # frame: color with a full row AND full column run... use: color c such that there exist i,j where row i has >=W-? cells of c
    best=None
    for c in cnt:
        if c==bg: continue
        rowsf=[i for i in range(H) if sum(1 for v in I[i] if v==c)>W*0.7]
        colsf=[j for j in range(W) if sum(1 for i in range(H) if I[i][j]==c)>H*0.7]
        if len(rowsf)>=1 and len(colsf)>=1:
            area=(max(rowsf)-min(rowsf)+1)*(max(colsf)-min(colsf)+1)
            if best is None or area>best[0]: best=(area,c,min(rowsf),max(colsf),min(colsf),max(colsf))
    _,c,a,b,l,r=best
    frameTL=(a,l); frameBR=(b,r); fsize=(b-a+1,r-l+1)
    inter_size=(fsize[0]-2,fsize[1]-2)
    # marks bbox: cells != bg and != frame color, outside frame rect
    markcells=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j]!=bg and I[i][j]!=c and not(a<=i<=b and l<=j<=r)]
    rs=[m[0] for m in markcells]; cs=[m[1] for m in markcells]
    M=[[I[i][j] for j in range(min(cs),max(cs)+1)] for i in range(min(rs),max(rs)+1)]
    nh,nw=len(M),len(M[0])
    si,sj=inter_size[0]//nh,inter_size[1]//nw
    out=[]
    for i in range(fsize[0]):
        row=[]
        for j in range(fsize[1]):
            if i in (a,b) or j in (l,r): row.append(c)
        out.append(row)
    for i in range(nh):
        for j in range(nw):
            vi=M[i][j]
            for a2 in range(si):
                for b2 in range(sj):
                    ri=a+1+i*si+a2; cj=l+1+j*sj+b2
                    if a<=ri<=b and l<=cj<=r: out[ri][cj]=vi if vi!=bg else 0
    return out
