# Frame rectangle = axis-aligned window with uniform non-bg border, max area, tie by most interior bg.
def find_frame(I):
    H,W=len(I),len(I[0])
    cnt=collections.Counter(x for r in I for x in r)
    bg=max(cnt,key=lambda c:cnt[c])
    best=None
    for a in range(H):
        for b in range(a+2,H):
            for l in range(W):
                for rr in range(l+2,W):
                    okring=True
                    for i in range(a,b+1):
                        if I[i][l]!=I[a][l]: okring=False;break
                        if I[i][rr]!=I[a][l]: okring=False;break
                    if not okring: continue
                    for j in range(l,rr+1):
                        if I[a][j]!=I[a][l]: okring=False;break
                        if I[b][j]!=I[a][l]: okring=False;break
                    if not okring: continue
                    inn=[I[i][j] for i in range(a+1,b) for j in range(l+1,rr)]
                    nb=sum(1 for v in inn if v==bg)
                    key=(-nb,(rr-l)*(b-a))
                    if best is None or key<best[0]: best=(key,I[a][l],a,b,l,rr)
